78f2848714940e1dac6",["Text"]="-----------------------------------\n-- Spell: Boost-MND\n-- Boosts MND for Allies in AoE\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useEnhancingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/boost-str.lua"]={["Path"]="scripts/actions/spells/white/boost-str.lua",["SHA256"]="9758a2679442ef14160b9415df9f7be9814d4c28fdc30c8ebce56eae063c0c4e",["Text"]="-----------------------------------\n-- Spell: Boost-STR\n-- Boosts STR for Allies in AoE\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useEnhancingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/boost-vit.lua"]={["Path"]="scripts/actions/spells/white/boost-vit.lua",["SHA256"]="0b5f459de5afc245f715b267f1a8d7dc8ad68f9204efef4a29ff93a5f69cffa4",["Text"]="-----------------------------------\n-- Spell: Boost-VIT\n-- Boosts VIT for Allies in AoE\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useEnhancingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/crusade.lua"]={["Path"]="scripts/actions/spells/white/crusade.lua",["SHA256"]="b2381ad6e49f90d78fc45a74c46118c99ae93e228cb41ca9d9d1b7c27237a89a",["Text"]="-----------------------------------\n-- Spell: Crusade\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useEnhancingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/cura.lua"]={["Path"]="scripts/actions/spells/white/cura.lua",["SHA256"]="14fb2f4ccdd076f0bb941d8f2e7b7bad7bb3790c655c096f97338c5c9f28d56a",["Text"]="-----------------------------------\n-- Spell: Cura\n-- Restores hp in area of effect. Self target only\n-- From what I understand, Cura's base potency is the same as Cure's.\n-- With Afflatus Misery Bonus, it can be as potent as a Curaga II\n-- Modeled after our Cure.lua, which was modeled after the below reference\n-- Shamelessly stolen from http://members.shaw.ca/pizza_steve/cure/Cure_Calculator.html\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    if caster:getID() ~= target:getID() then\n        return xi.msg.basic.CANNOT_PERFORM_TARG\n    else\n        return 0\n    end\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local divisor = 0\n    local constant = 0\n    local basepower = 0\n    local power = 0\n    local basecure = 0\n    local final = 0\n\n    local minCure = 10\n    if xi.settings.main.USE_OLD_CURE_FORMULA then\n        power = getCurePowerOld(caster)\n        divisor = 1\n        constant = -10\n        if power > 100 then\n                divisor = 57\n                constant = 29.125\n        elseif power > 60 then\n                divisor = 2\n                constant = 5\n        end\n    else\n        power = getCurePower(caster)\n        if power < 20 then\n            divisor = 4\n            constant = 10\n            basepower = 0\n        elseif power < 40 then\n            divisor =  1.3333\n            constant = 15\n            basepower = 20\n        elseif power < 125 then\n            divisor = 8.5\n            constant = 30\n            basepower = 40\n        elseif power < 200 then\n            divisor = 15\n            constant = 40\n            basepower = 125\n        elseif power < 600 then\n            divisor = 20\n            constant = 40\n            basepower = 200\n        else\n            divisor = 999999\n            constant = 65\n            basepower = 0\n        end\n    end\n\n    if xi.settings.main.USE_OLD_CURE_FORMULA then\n        basecure = getBaseCureOld(power, divisor, constant)\n    else\n        basecure = getBaseCure(power, divisor, constant, basepower)\n    end\n\n    --Apply Afflatus Misery Bonus to Final Result\n    if caster:hasStatusEffect(xi.effect.AFFLATUS_MISERY) then\n        if caster:getID() == target:getID() then -- Let's use a local var to hold the power of Misery so the boost is applied to all targets,\n            caster:setLocalVar('Misery_Power', caster:getMod(xi.mod.AFFLATUS_MISERY))\n        end\n\n        local misery = caster:getLocalVar('Misery_Power')\n        --THIS IS LARELY SEMI-EDUCATED GUESSWORK. THERE IS NOT A\n        --LOT OF CONCRETE INFO OUT THERE ON CURA THAT I COULD FIND\n\n        --If the target max affluent misery bonus\n        --according to tests I found seems to cap out at most\n        --people about 125 misery. With that in mind, if you\n        --were hitting the Cure I cap of 65hp, then each misery\n        --point would boost your Cura by about 1hp, capping at ~175hp\n        --So with lack of available formula documentation, I'll go with that.\n\n        basecure = basecure + misery\n\n        if basecure > 175 then\n            basecure = 175\n        end\n\n        --Afflatus Misery Mod Gets Used Up\n        caster:setMod(xi.mod.AFFLATUS_MISERY, 0)\n    end\n\n    final = getCureFinal(caster, spell, basecure, minCure, false)\n    final = final + (final * (target:getMod(xi.mod.CURE_POTENCY_RCVD) / 100))\n\n    --Applying server mods\n    final = final * xi.settings.main.CURE_POWER\n\n    target:addHP(final)\n\n    target:wakeUp()\n\n    -- pass in fixed enmity values of 50 CE and 50 VE\n    caster:updateEnmityFromCure(target, final, 50, 50)\n\n    if target:getID() == spell:getPrimaryTargetID() then\n        spell:setMsg(xi.msg.basic.MAGIC_RECOVERS_HP)\n    else\n        spell:setMsg(xi.msg.basic.SELF_HEAL_SECONDARY)\n    end\n\n    local mpBonusPercent = (final * caster:getMod(xi.mod.CURE2MP_PERCENT)) / 100\n    if mpBonusPercent > 0 then\n        caster:addMP(mpBonusPercent)\n    end\n\n    return final\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/cura_ii.lua"]={["Path"]="scripts/actions/spells/white/cura_ii.lua",["SHA256"]="669c1954c7cf49faacd5507b9ad12fb61d34185da5983fd6dca9085296c586b5",["Text"]="-----------------------------------\n-- Spell: Cura\n-- Restores hp in area of effect. Self target only\n-- From what I understand, Cura's base potency is the same as Cure II's.\n-- With Afflatus Misery Bonus, it can be as potent as a Curaga III\n-- Modeled after our cure_ii.lua, which was modeled after the below reference\n-- Shamelessly stolen from http://members.shaw.ca/pizza_steve/cure/Cure_Calculator.html\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    if caster:getID() ~= target:getID() then\n        return xi.msg.basic.CANNOT_PERFORM_TARG\n    else\n        return 0\n    end\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local divisor = 0\n    local constant = 0\n    local basepower = 0\n    local power = 0\n    local basecure = 0\n    local final = 0\n\n    local minCure = 60\n    if xi.settings.main.USE_OLD_CURE_FORMULA then\n        power = getCurePowerOld(caster)\n        divisor = 1\n        constant = 20\n        if power > 170 then\n                divisor = 35.6666\n                constant = 87.62\n        elseif power > 110 then\n                divisor = 2\n                constant = 47.5\n        end\n    else\n        power = getCurePower(caster)\n        if power < 70 then\n            divisor = 1\n            constant = 60\n            basepower = 40\n        elseif power < 125 then\n            divisor = 5.5\n            constant = 90\n            basepower = 70\n        elseif power < 200 then\n            divisor = 7.5\n            constant = 100\n            basepower = 125\n        elseif power < 400 then\n            divisor = 10\n            constant = 110\n            basepower = 200\n        elseif power < 700 then\n            divisor = 20\n            constant = 130\n            basepower = 400\n        else\n            divisor = 999999\n            constant = 145\n            basepower = 0\n        end\n    end\n\n    if xi.settings.main.USE_OLD_CURE_FORMULA then\n        basecure = getBaseCureOld(power, divisor, constant)\n    else\n        basecure = getBaseCure(power, divisor, constant, basepower)\n    end\n\n    --Apply Afflatus Misery Bonus to Final Result\n    if caster:hasStatusEffect(xi.effect.AFFLATUS_MISERY) then\n        if caster:getID() == target:getID() then -- Let's use a local var to hold the power of Misery so the boost is applied to all targets,\n            caster:setLocalVar('Misery_Power', caster:getMod(xi.mod.AFFLATUS_MISERY))\n        end\n\n        local misery = caster:getLocalVar('Misery_Power')\n\n        --THIS IS LARELY SEMI-EDUCATED GUESSWORK. THERE IS NOT A\n        --LOT OF CONCRETE INFO OUT THERE ON CURA THAT I COULD FIND\n\n        --Not very much documentation for Cura II known at all.\n        --As with Cura, the Afflatus Misery bonus can boost this spell up\n        --to roughly the level of a Curaga 3. For Cura I vs Curaga II,\n        --this is document at ~175HP, 15HP less than the cap of 190HP. So\n        --for Cura II, i'll go with 15 less than the cap of Curaga III (390): 375\n        --So with lack of available formula documentation, I'll go with that.\n\n        basecure = basecure + misery\n\n        if basecure > 375 then\n            basecure = 375\n        end\n\n        --Afflatus Misery Mod Gets Used Up\n        caster:setMod(xi.mod.AFFLATUS_MISERY, 0)\n    end\n\n    final = getCureFinal(caster, spell, basecure, minCure, false)\n    final = final + (final * (target:getMod(xi.mod.CURE_POTENCY_RCVD) / 100))\n\n    --Applying server mods\n    final = final * xi.settings.main.CURE_POWER\n\n    target:addHP(final)\n\n    target:wakeUp()\n\n    -- pass in fixed enmity values of 75 CE and 75 VE\n    caster:updateEnmityFromCure(target, final, 75, 75)\n\n    if target:getID() == spell:getPrimaryTargetID() then\n        spell:setMsg(xi.msg.basic.MAGIC_RECOVERS_HP)\n    else\n        spell:setMsg(xi.msg.basic.SELF_HEAL_SECONDARY)\n    end\n\n    local mpBonusPercent = (final * caster:getMod(xi.mod.CURE2MP_PERCENT)) / 100\n    if mpBonusPercent > 0 then\n        caster:addMP(mpBonusPercent)\n    end\n\n    return final\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/cura_iii.lua"]={["Path"]="scripts/actions/spells/white/cura_iii.lua",["SHA256"]="dd25d17f0f1cbd38498ae01652f7853ca2273cc53838af08794aa8fc803fbf8a",["Text"]="-----------------------------------\n-- Spell: Cura III\n-- Restores hp in area of effect. Self target only\n-- From what I understand, Cura III's base potency is the same as Cure III's.\n-- With Afflatus Misery Bonus, it can be as potent as a Curaga IV\n-- Modeled after our cure_iii.lua, which was modeled after the below reference\n-- Shamelessly stolen from http://members.shaw.ca/pizza_steve/cure/Cure_Calculator.html\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    if caster:getID() ~= target:getID() then\n        return xi.msg.basic.CANNOT_PERFORM_TARG\n    else\n        return 0\n    end\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local divisor = 0\n    local constant = 0\n    local basepower = 0\n    local power = 0\n    local basecure = 0\n    local final = 0\n\n    local minCure = 130\n    if xi.settings.main.USE_OLD_CURE_FORMULA then\n        power = getCurePowerOld(caster)\n        divisor = 1\n        constant = 70\n        if power > 300 then\n            divisor = 15.6666\n            constant = 180.43\n        elseif power > 180 then\n            divisor = 2\n            constant = 115\n        end\n    else\n        power = getCurePower(caster)\n        if power < 125 then\n            divisor = 2.2\n            constant = 130\n            basepower = 70\n        elseif power < 200 then\n            divisor =  75 / 65\n            constant = 155\n            basepower = 125\n        elseif power < 300 then\n            divisor = 2.5\n            constant = 220\n            basepower = 200\n        elseif power < 700 then\n            divisor = 5\n            constant = 260\n            basepower = 300\n        else\n            divisor = 999999\n            constant = 340\n            basepower = 0\n        end\n    end\n\n    if xi.settings.main.USE_OLD_CURE_FORMULA then\n        basecure = getBaseCureOld(power, divisor, constant)\n    else\n        basecure = getBaseCure(power, divisor, constant, basepower)\n    end\n\n    --Apply Afflatus Misery Bonus to the Result\n    if caster:hasStatusEffect(xi.effect.AFFLATUS_MISERY) then\n        if caster:getID() == target:getID() then -- Let's use a local var to hold the power of Misery so the boost is applied to all targets,\n            caster:setLocalVar('Misery_Power', caster:getMod(xi.mod.AFFLATUS_MISERY))\n        end\n\n        local misery = caster:getLocalVar('Misery_Power')\n\n        --THIS IS LARELY SEMI-EDUCATED GUESSWORK. THERE IS NOT A\n        --LOT OF CONCRETE INFO OUT THERE ON CURA THAT I COULD FIND\n\n        --Not very much documentation for Cura II known at all.\n        --As with Cura, the Afflatus Misery bonus can boost this spell up\n        --to roughly the level of a Curaga 4. For Cura II vs Curaga III,\n        --this is document at ~375HP, 15HP less than the cap of 390HP. So\n        --for Cura II, i'll go with 15 less than the cap of Curaga IV (690): 675\n        --So with lack of available formula documentation, I'll go with that.\n\n        basecure = basecure + misery\n\n        if basecure > 675 then\n            basecure = 675\n        end\n\n        --Afflatus Misery Mod Gets Used Up\n        caster:setMod(xi.mod.AFFLATUS_MISERY, 0)\n    end\n\n    final = getCureFinal(caster, spell, basecure, minCure, false)\n    final = final + (final * (target:getMod(xi.mod.CURE_POTENCY_RCVD) / 100))\n\n    --Applying server mods\n    final = final * xi.settings.main.CURE_POWER\n\n    local diff = (target:getMaxHP() - target:getHP())\n    if final > diff then\n        final = diff\n    end\n\n    target:addHP(final)\n\n    target:wakeUp()\n\n    -- pass in fixed enmity values of 100 CE and 100 VE\n    caster:updateEnmityFromCure(target, final, 100, 100)\n\n    if target:getID() == spell:getPrimaryTargetID() then\n        spell:setMsg(xi.msg.basic.MAGIC_RECOVERS_HP)\n    else\n        spell:setMsg(xi.msg.basic.SELF_HEAL_SECONDARY)\n    end\n\n    local mpBonusPercent = (final * caster:getMod(xi.mod.CURE2MP_PERCENT)) / 100\n    if mpBonusPercent > 0 then\n        caster:addMP(mpBonusPercent)\n    end\n\n    return final\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/curaga.lua"]={["Path"]="scripts/actions/spells/white/curaga.lua",["SHA256"]="b9389c850a5af3723d12d38acdf4e70b564afb81d6f1f7a5ae11f2db8c7b81e3",["Text"]="-----------------------------------\n-- Spell: Curaga\n-- Restores HP of all party members within area of effect.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local minCure = 60\n\n    local divisor = 1\n    local constant = 20\n    local power = getCurePowerOld(caster)\n    if power > 170 then\n        divisor = 35.6666\n        constant = 87.62\n    elseif power > 110 then\n        divisor =  2\n        constant = 47.5\n    end\n\n    local final = getCureFinal(caster, spell, getBaseCureOld(power, divisor, constant), minCure, false)\n\n    final = final + (final * (target:getMod(xi.mod.CURE_POTENCY_RCVD) / 100))\n\n    --Applying server mods\n    final = final * xi.settings.main.CURE_POWER\n\n    local diff = (target:getMaxHP() - target:getHP())\n    if final > diff then\n        final = diff\n    end\n\n    target:addHP(final)\n\n    target:wakeUp()\n    caster:updateEnmityFromCure(target, final)\n\n    if target:getID() == spell:getPrimaryTargetID() then\n        spell:setMsg(xi.msg.basic.MAGIC_RECOVERS_HP)\n    else\n        spell:setMsg(xi.msg.basic.SELF_HEAL_SECONDARY)\n    end\n\n    local mpBonusPercent = (final * caster:getMod(xi.mod.CURE2MP_PERCENT)) / 100\n    if mpBonusPercent > 0 then\n        caster:addMP(mpBonusPercent)\n    end\n\n    return final\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/curaga_ii.lua"]={["Path"]="scripts/actions/spells/white/curaga_ii.lua",["SHA256"]="efa84f80eae150b99217f09e0c15485ddceb8808fa53fb34dd98643bd2792375",["Text"]="-----------------------------------\n-- Spell: Curaga II\n-- Restores HP of all party members within area of effect.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local minCure = 130\n\n    local divisor = 1\n    local constant = 70\n    local power = getCurePowerOld(caster)\n    if power > 300 then\n        divisor = 15.6666\n        constant = 180.43\n    elseif power > 180 then\n        divisor =  2\n        constant = 115\n    end\n\n    local final = getCureFinal(caster, spell, getBaseCureOld(power, divisor, constant), minCure, false)\n\n    final = final + (final * (target:getMod(xi.mod.CURE_POTENCY_RCVD) / 100))\n\n    --Applying server mods\n    final = final * xi.settings.main.CURE_POWER\n\n    local diff = (target:getMaxHP() - target:getHP())\n    if final > diff then\n        final = diff\n    end\n\n    target:addHP(final)\n\n    target:wakeUp()\n    caster:updateEnmityFromCure(target, final)\n\n    if target:getID() == spell:getPrimaryTargetID() then\n        spell:setMsg(xi.msg.basic.MAGIC_RECOVERS_HP)\n    else\n        spell:setMsg(xi.msg.basic.SELF_HEAL_SECONDARY)\n    end\n\n    local mpBonusPercent = (final * caster:getMod(xi.mod.CURE2MP_PERCENT)) / 100\n    if mpBonusPercent > 0 then\n        caster:addMP(mpBonusPercent)\n    end\n\n    return final\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/curaga_iii.lua"]={["Path"]="scripts/actions/spells/white/curaga_iii.lua",["SHA256"]="53dc7484e697a59f9e4761c7ef183eafeb37493b218bc3e4b4ff7d097e4c863f",["Text"]="-----------------------------------\n-- Spell: Curaga III\n-- Restores HP of all party members within area of effect.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local minCure = 270\n\n    local divisor = 0.6666\n    local constant = 165\n    local power = getCurePowerOld(caster)\n    if power > 460 then\n        divisor = 6.5\n        constant = 354.6666\n    elseif power > 220 then\n        divisor = 2\n        constant = 275\n    end\n\n    local final = getCureFinal(caster, spell, getBaseCureOld(power, divisor, constant), minCure, false)\n\n    final = final + (final * (target:getMod(xi.mod.CURE_POTENCY_RCVD) / 100))\n\n    --Applying server mods\n    final = final * xi.settings.main.CURE_POWER\n\n    local diff = (target:getMaxHP() - target:getHP())\n    if final > diff then\n        final = diff\n    end\n\n    target:addHP(final)\n\n    target:wakeUp()\n    caster:updateEnmityFromCure(target, final)\n\n    if target:getID() == spell:getPrimaryTargetID() then\n        spell:setMsg(xi.msg.basic.MAGIC_RECOVERS_HP)\n    else\n        spell:setMsg(xi.msg.basic.SELF_HEAL_SECONDARY)\n    end\n\n    local mpBonusPercent = (final * caster:getMod(xi.mod.CURE2MP_PERCENT)) / 100\n    if mpBonusPercent > 0 then\n        caster:addMP(mpBonusPercent)\n    end\n\n    return final\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/curaga_iv.lua"]={["Path"]="scripts/actions/spells/white/curaga_iv.lua",["SHA256"]="c8551fc8569d86fc341863d42ce581b38a08ab5872e0222fe37786bcf15b28ec",["Text"]="-----------------------------------\n-- Spell: Curaga IV\n-- Restores HP of all party members within area of effect.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local minCure = 450\n\n    local divisor = 0.6666\n    local constant = 330\n    local power = getCurePowerOld(caster)\n    if power > 560 then\n        divisor = 2.8333\n        constant = 591.2\n    elseif power > 320 then\n        divisor =  1\n        constant = 410\n    end\n\n    local final = getCureFinal(caster, spell, getBaseCureOld(power, divisor, constant), minCure, false)\n\n    final = final + (final * (target:getMod(xi.mod.CURE_POTENCY_RCVD) / 100))\n\n    --Applying server mods\n    final = final * xi.settings.main.CURE_POWER\n\n    local diff = (target:getMaxHP() - target:getHP())\n    if final > diff then\n        final = diff\n    end\n\n    target:addHP(final)\n\n    target:wakeUp()\n    caster:updateEnmityFromCure(target, final)\n\n    if target:getID() == spell:getPrimaryTargetID() then\n        spell:setMsg(xi.msg.basic.MAGIC_RECOVERS_HP)\n    else\n        spell:setMsg(xi.msg.basic.SELF_HEAL_SECONDARY)\n    end\n\n    local mpBonusPercent = (final * caster:getMod(xi.mod.CURE2MP_PERCENT)) / 100\n    if mpBonusPercent > 0 then\n        caster:addMP(mpBonusPercent)\n    end\n\n    return final\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/curaga_v.lua"]={["Path"]="scripts/actions/spells/white/curaga_v.lua",["SHA256"]="da3695cc58166251e26f2ca47217fd72818d939909c51cda77ec5479577bb131",["Text"]="-----------------------------------\n-- Spell: Curaga V\n-- Restores HP of all party members within area of effect.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local minCure = 600\n\n    local divisor = 1\n    local constant = 570\n    local power = getCurePowerOld(caster)\n    if power > 780 then\n        divisor = 2.667\n        constant = 814--this is too powerful and needs to be fixed when the rest of the curaga 5 numbers are determined\n    end\n\n    local final = getCureFinal(caster, spell, getBaseCureOld(power, divisor, constant), minCure, false)\n\n    final = final + (final * (target:getMod(xi.mod.CURE_POTENCY_RCVD) / 100))\n\n    --Applying server mods\n    final = final * xi.settings.main.CURE_POWER\n\n    local diff = (target:getMaxHP() - target:getHP())\n    if final > diff then\n        final = diff\n    end\n\n    target:addHP(final)\n\n    target:wakeUp()\n    caster:updateEnmityFromCure(target, final)\n\n    if target:getID() == spell:getPrimaryTargetID() then\n        spell:setMsg(xi.msg.basic.MAGIC_RECOVERS_HP)\n    else\n        spell:setMsg(xi.msg.basic.SELF_HEAL_SECONDARY)\n    end\n\n    local mpBonusPercent = (final * caster:getMod(xi.mod.CURE2MP_PERCENT)) / 100\n    if mpBonusPercent > 0 then\n        caster:addMP(mpBonusPercent)\n    end\n\n    return final\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/cure.lua"]={["Path"]="scripts/actions/spells/white/cure.lua",["SHA256"]="bc0175ec60554b9727c348fdb67cc30014d8d6724c457e1c5a3b13309916efd8",["Text"]="-----------------------------------\n-- Spell: Cure\n-- Restores target's HP.\n-- Shamelessly stolen from http://members.shaw.ca/pizza_steve/cure/Cure_Calculator.html\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local divisor = 0\n    local constant = 0\n    local basepower = 0\n    local power = 0\n    local basecure = 0\n    local final = 0\n\n    local minCure = 10\n    if xi.settings.main.USE_OLD_CURE_FORMULA then\n        power = getCurePowerOld(caster)\n        divisor = 1\n        constant = -10\n        if power > 100 then\n            divisor = 57\n            constant = 29.125\n        elseif power > 60 then\n            divisor = 2\n            constant = 5\n        end\n    else\n        power = getCurePower(caster)\n        if power < 20 then\n            divisor = 4\n            constant = 10\n            basepower = 0\n        elseif power < 40 then\n            divisor =  1.3333\n            constant = 15\n            basepower = 20\n        elseif power < 125 then\n            divisor = 8.5\n            constant = 30\n            basepower = 40\n        elseif power < 200 then\n            divisor = 15\n            constant = 40\n            basepower = 125\n        elseif power < 600 then\n            divisor = 20\n            constant = 40\n            basepower = 200\n        else\n            divisor = 999999\n            constant = 65\n            basepower = 0\n        end\n    end\n\n    if isValidHealTarget(caster, target) then\n        if xi.settings.main.USE_OLD_CURE_FORMULA then\n            basecure = getBaseCureOld(power, divisor, constant)\n        else\n            basecure = getBaseCure(power, divisor, constant, basepower)\n        end\n\n        final = getCureFinal(caster, spell, basecure, minCure, false)\n        if\n            caster:hasStatusEffect(xi.effect.AFFLATUS_SOLACE) and\n            not target:hasStatusEffect(xi.effect.STONESKIN)\n        then\n            local solaceStoneskin = 0\n            local equippedBody = xi.equipment.getUsableEquipID(caster, xi.slot.BODY)\n            if equippedBody == xi.item.ORISON_BLIAUT_P1 then\n                solaceStoneskin = math.floor(final * 0.30)\n            elseif equippedBody == xi.item.ORISON_BLIAUT_P2 then\n                solaceStoneskin = math.floor(final * 0.35)\n            else\n                solaceStoneskin = math.floor(final * 0.25)\n            end\n\n            solaceStoneskin = solaceStoneskin * (1 + caster:getMerit(xi.merit.ANIMUS_SOLACE) / 100)\n\n            target:addStatusEffect(xi.effect.STONESKIN, { power = solaceStoneskin, duration = 25, origin = caster, tier = 1 })\n        end\n\n        final = final + (final * (target:getMod(xi.mod.CURE_POTENCY_RCVD) / 100))\n\n        --Applying server mods\n        final = final * xi.settings.main.CURE_POWER\n\n        local diff = (target:getMaxHP() - target:getHP())\n        if final > diff then\n            final = diff\n        end\n\n        target:addHP(final)\n\n        target:wakeUp()\n        caster:updateEnmityFromCure(target, final)\n    else\n        -- no effect if player casted on mob\n\n        if target:isUndead() then\n            spell:setMsg(xi.msg.basic.MAGIC_DMG)\n\n            final = xi.spells.damage.useDamageSpell(caster, target, spell)\n        elseif caster:getObjType() == xi.objType.PC then\n            spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n        else\n            -- e.g. monsters healing themselves.\n            if xi.settings.main.USE_OLD_CURE_FORMULA then\n                basecure = getBaseCureOld(power, divisor, constant)\n            else\n                basecure = getBaseCure(power, divisor, constant, basepower)\n            end\n\n            final = getCureFinal(caster, spell, basecure, minCure, false)\n            local diff = (target:getMaxHP() - target:getHP())\n            if final > diff then\n                final = diff\n            end\n\n            target:addHP(final)\n        end\n    end\n\n    local mpBonusPercent = (final * caster:getMod(xi.mod.CURE2MP_PERCENT)) / 100\n    if mpBonusPercent > 0 then\n        caster:addMP(mpBonusPercent)\n    end\n\n    return final\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/cure_ii.lua"]={["Path"]="scripts/actions/spells/white/cure_ii.lua",["SHA256"]="76df196661976147323d12796086eb7b93d09b8b737b5e34a87007f81d2d269e",["Text"]="-----------------------------------\n-- Spell: Cure II\n-- Restores target's HP.\n-- Shamelessly stolen from http://members.shaw.ca/pizza_steve/cure/Cure_Calculator.html\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local divisor = 0\n    local constant = 0\n    local basepower = 0\n    local power = 0\n    local basecure = 0\n    local final = 0\n\n    local minCure = 60\n    if xi.settings.main.USE_OLD_CURE_FORMULA then\n        power = getCurePowerOld(caster)\n        divisor = 1\n        constant = 20\n        if power > 170 then\n            divisor = 35.6666\n            constant = 87.62\n        elseif power > 110 then\n            divisor = 2\n            constant = 47.5\n        end\n    else\n        power = getCurePower(caster)\n        if power < 70 then\n            divisor = 1\n            constant = 60\n            basepower = 40\n        elseif power < 125 then\n            divisor = 5.5\n            constant = 90\n            basepower = 70\n        elseif power < 200 then\n            divisor = 7.5\n            constant = 100\n            basepower = 125\n        elseif power < 400 then\n            divisor = 10\n            constan