pplying server mods\n        final = final * xi.settings.main.CURE_POWER\n\n        local diff = (target:getMaxHP() - target:getHP())\n        if final > diff then\n            final = diff\n        end\n\n        target:addHP(final)\n\n        target:wakeUp()\n        caster:updateEnmityFromCure(target, final)\n    else\n        if target:isUndead() then\n            spell:setMsg(xi.msg.basic.MAGIC_DMG)\n\n            final = xi.spells.damage.useDamageSpell(caster, target, spell)\n        elseif caster:getObjType() == xi.objType.PC then\n            spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n        else\n            -- e.g. monsters healing themselves.\n            if xi.settings.main.USE_OLD_CURE_FORMULA then\n                basecure = getBaseCureOld(power, divisor, constant)\n            else\n                basecure = getBaseCure(power, divisor, constant, basepower)\n            end\n\n            final = getCureFinal(caster, spell, basecure, minCure, false)\n            local diff = (target:getMaxHP() - target:getHP())\n            if final > diff then\n                final = diff\n            end\n\n            target:addHP(final)\n        end\n    end\n\n    local mpBonusPercent = (final * caster:getMod(xi.mod.CURE2MP_PERCENT)) / 100\n    if mpBonusPercent > 0 then\n        caster:addMP(mpBonusPercent)\n    end\n\n    return final\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/cure_iv.lua"]={["Path"]="scripts/actions/spells/white/cure_iv.lua",["SHA256"]="3c4d41af7455c568ac3dbdf0250fa7179e093a59798a1d5bae29d1cb1a6eb4ca",["Text"]="-----------------------------------\n-- Spell: Cure IV\n-- Restores target's HP.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local divisor = 0\n    local constant = 0\n    local basepower = 0\n    local power = 0\n    local basecure = 0\n    local final = 0\n\n    local minCure = 270\n    if xi.settings.main.USE_OLD_CURE_FORMULA then\n        power = getCurePowerOld(caster)\n        divisor = 0.6666\n        constant = 165\n        if power > 460 then\n            divisor = 6.5\n            constant = 354.6666\n        elseif power > 220 then\n            divisor = 2\n            constant = 275\n        end\n    else\n        power = getCurePower(caster)\n        if power < 200 then\n            divisor = 1\n            constant = 270\n            basepower = 70\n        elseif power < 300 then\n            divisor =  2\n            constant = 400\n            basepower = 200\n        elseif power < 400 then\n            divisor = 10 / 7\n            constant = 450\n            basepower = 300\n        elseif power < 700 then\n            divisor = 2.5\n            constant = 520\n            basepower = 400\n        else\n            divisor = 999999\n            constant = 640\n            basepower = 0\n        end\n    end\n\n    if isValidHealTarget(caster, target) then\n        if xi.settings.main.USE_OLD_CURE_FORMULA then\n            basecure = getBaseCureOld(power, divisor, constant)\n        else\n            basecure = getBaseCure(power, divisor, constant, basepower)\n        end\n\n        final = getCureFinal(caster, spell, basecure, minCure, false)\n        if\n            caster:hasStatusEffect(xi.effect.AFFLATUS_SOLACE) and\n            not target:hasStatusEffect(xi.effect.STONESKIN)\n        then\n            local solaceStoneskin = 0\n            local equippedBody = xi.equipment.getUsableEquipID(caster, xi.slot.BODY)\n            if equippedBody == xi.item.ORISON_BLIAUT_P1 then\n                solaceStoneskin = math.floor(final * 0.30)\n            elseif equippedBody == xi.item.ORISON_BLIAUT_P2 then\n                solaceStoneskin = math.floor(final * 0.35)\n            else\n                solaceStoneskin = math.floor(final * 0.25)\n            end\n\n            solaceStoneskin = solaceStoneskin * (1 + caster:getMerit(xi.merit.ANIMUS_SOLACE) / 100)\n\n            target:addStatusEffect(xi.effect.STONESKIN, { power = solaceStoneskin, duration = 25, origin = caster, tier = 1 })\n        end\n\n        final = final + (final * (target:getMod(xi.mod.CURE_POTENCY_RCVD) / 100))\n\n        --Applying server mods\n        final = final * xi.settings.main.CURE_POWER\n\n        local diff = (target:getMaxHP() - target:getHP())\n        if final > diff then\n            final = diff\n        end\n\n        target:addHP(final)\n        target:wakeUp()\n        caster:updateEnmityFromCure(target, final)\n    else\n        if target:isUndead() then\n            spell:setMsg(xi.msg.basic.MAGIC_DMG)\n\n            final = xi.spells.damage.useDamageSpell(caster, target, spell)\n        elseif caster:getObjType() == xi.objType.PC then\n            spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n        else\n            -- e.g. monsters healing themselves.\n            if xi.settings.main.USE_OLD_CURE_FORMULA then\n                basecure = getBaseCureOld(power, divisor, constant)\n            else\n                basecure = getBaseCure(power, divisor, constant, basepower)\n            end\n\n            final = getCureFinal(caster, spell, basecure, minCure, false)\n            local diff = (target:getMaxHP() - target:getHP())\n            if final > diff then\n                final = diff\n            end\n\n            target:addHP(final)\n        end\n    end\n\n    local mpBonusPercent = (final * caster:getMod(xi.mod.CURE2MP_PERCENT)) / 100\n    if mpBonusPercent > 0 then\n        caster:addMP(mpBonusPercent)\n    end\n\n    return final\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/cure_v.lua"]={["Path"]="scripts/actions/spells/white/cure_v.lua",["SHA256"]="27588936b1319509c75418fdf4147707de33cda4a6bf808820af7f0d85ca9b47",["Text"]="-----------------------------------\n-- Spell: Cure V\n-- Restores target's HP.\n-- Shamelessly stolen from http://members.shaw.ca/pizza_steve/cure/Cure_Calculator.html\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local divisor = 0\n    local constant = 0\n    local basepower = 0\n    local power = 0\n    local basecure = 0\n    local final = 0\n\n    local minCure = 450\n    if xi.settings.main.USE_OLD_CURE_FORMULA then\n        power = getCurePowerOld(caster)\n        divisor = 0.6666\n        constant = 330\n        if power > 560 then\n            divisor = 2.8333\n            constant = 591.2\n        elseif power > 320 then\n            divisor = 1\n            constant = 410\n        end\n    else\n        power = getCurePower(caster)\n        if power < 150 then\n            divisor = 0.70\n            constant = 450\n            basepower = 80\n        elseif power < 190 then\n            divisor =  1.25\n            constant = 550\n            basepower = 150\n        elseif power < 260 then\n            divisor = 70 / 38\n            constant = 582\n            basepower = 190\n        elseif power < 300 then\n            divisor = 2\n            constant = 620\n            basepower = 260\n        elseif power < 500 then\n            divisor = 2.5\n            constant = 640\n            basepower = 300\n        elseif power < 700 then\n            divisor = 10 / 3\n            constant = 720\n            basepower = 500\n        else\n            divisor = 999999\n            constant = 780\n            basepower = 0\n        end\n    end\n\n    if isValidHealTarget(caster, target) then -- e.g. is a PC and not a monster (?)\n        if xi.settings.main.USE_OLD_CURE_FORMULA then\n            basecure = getBaseCureOld(power, divisor, constant)\n        else\n            basecure = getBaseCure(power, divisor, constant, basepower)\n        end\n\n        final = getCureFinal(caster, spell, basecure, minCure, false)\n        if\n            caster:hasStatusEffect(xi.effect.AFFLATUS_SOLACE) and\n            not target:hasStatusEffect(xi.effect.STONESKIN)\n        then\n            local solaceStoneskin = 0\n            local equippedBody = xi.equipment.getUsableEquipID(caster, xi.slot.BODY)\n            if equippedBody == xi.item.ORISON_BLIAUT_P1 then\n                solaceStoneskin = math.floor(final * 0.30)\n            elseif equippedBody == xi.item.ORISON_BLIAUT_P2 then\n                solaceStoneskin = math.floor(final * 0.35)\n            else\n                solaceStoneskin = math.floor(final * 0.25)\n            end\n\n            solaceStoneskin = solaceStoneskin * (1 + caster:getMerit(xi.merit.ANIMUS_SOLACE) / 100)\n\n            target:addStatusEffect(xi.effect.STONESKIN, { power = solaceStoneskin, duration = 25, origin = caster, tier = 1 })\n        end\n\n        final = final + (final * (target:getMod(xi.mod.CURE_POTENCY_RCVD) / 100))\n\n        --Applying server mods\n        final = final * xi.settings.main.CURE_POWER\n\n        local diff = (target:getMaxHP() - target:getHP())\n        if final > diff then\n            final = diff\n        end\n\n        target:addHP(final)\n\n        target:wakeUp()\n\n        -- pass in fixed enmity values of 300 CE and 600 VE\n        caster:updateEnmityFromCure(target, final, 300, 600)\n\n    else\n        if target:isUndead() then -- e.g. PCs healing skeles for damage (?)\n            spell:setMsg(xi.msg.basic.MAGIC_DMG)\n\n            final = xi.spells.damage.useDamageSpell(caster, target, spell)\n        elseif caster:getObjType() == xi.objType.PC then\n            spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n        else\n            -- e.g. monsters healing themselves.\n            if xi.settings.main.USE_OLD_CURE_FORMULA then\n                basecure = getBaseCureOld(power, divisor, constant)\n            else\n                basecure = getBaseCure(power, divisor, constant, basepower)\n            end\n\n            final = getCureFinal(caster, spell, basecure, minCure, false)\n            local diff = (target:getMaxHP() - target:getHP())\n            if final > diff then\n                final = diff\n            end\n\n            target:addHP(final)\n        end\n    end\n\n    local mpBonusPercent = (final * caster:getMod(xi.mod.CURE2MP_PERCENT)) / 100\n    if mpBonusPercent > 0 then\n        caster:addMP(mpBonusPercent)\n    end\n\n    return final\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/cure_vi.lua"]={["Path"]="scripts/actions/spells/white/cure_vi.lua",["SHA256"]="95b64000ca44ee96bfe0019789876a52a0445694563ca443a0919361ebe556e4",["Text"]="-----------------------------------\n-- Spell: Cure VI\n-- Restores target's HP.\n-- Shamelessly stolen from http://members.shaw.ca/pizza_steve/cure/Cure_Calculator.html\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local divisor = 0\n    local constant = 0\n    local basepower = 0\n    local power = 0\n    local basecure = 0\n    local final = 0\n\n    local minCure = 600\n    power = getCurePower(caster)\n    if power < 210 then\n        divisor = 1.5\n        constant = 600\n        basepower = 90\n    elseif power < 300 then\n        divisor =  0.9\n        constant = 680\n        basepower = 210\n    elseif power < 400 then\n        divisor = 10 / 7\n        constant = 780\n        basepower = 300\n    elseif power < 500 then\n        divisor = 2.5\n        constant = 850\n        basepower = 400\n    elseif power < 700 then\n        divisor = 5 / 3\n        constant = 890\n        basepower = 500\n    else\n        divisor = 999999\n        constant = 1010\n        basepower = 0\n    end\n\n    if isValidHealTarget(caster, target) then\n        basecure = getBaseCure(power, divisor, constant, basepower)\n        final = getCureFinal(caster, spell, basecure, minCure, false)\n        if\n            caster:hasStatusEffect(xi.effect.AFFLATUS_SOLACE) and\n            not target:hasStatusEffect(xi.effect.STONESKIN)\n        then\n            local solaceStoneskin = 0\n            local equippedBody = xi.equipment.getUsableEquipID(caster, xi.slot.BODY)\n            if equippedBody == xi.item.ORISON_BLIAUT_P1 then\n                solaceStoneskin = math.floor(final * 0.30)\n            elseif equippedBody == xi.item.ORISON_BLIAUT_P2 then\n                solaceStoneskin = math.floor(final * 0.35)\n            else\n                solaceStoneskin = math.floor(final * 0.25)\n            end\n\n            solaceStoneskin = solaceStoneskin * (1 + caster:getMerit(xi.merit.ANIMUS_SOLACE) / 100)\n\n            target:addStatusEffect(xi.effect.STONESKIN, { power = solaceStoneskin, duration = 25, origin = caster, tier = 1 })\n        end\n\n        final = final + (final * (target:getMod(xi.mod.CURE_POTENCY_RCVD) / 100))\n\n        --Applying server mods\n        final = final * xi.settings.main.CURE_POWER\n\n        local diff = (target:getMaxHP() - target:getHP())\n        if final > diff then\n            final = diff\n        end\n\n        target:restoreHP(final)\n\n        target:wakeUp()\n        caster:updateEnmityFromCure(target, final)\n    else\n        if target:isUndead() then\n            spell:setMsg(xi.msg.basic.MAGIC_DMG)\n\n            final = xi.spells.damage.useDamageSpell(caster, target, spell)\n        elseif caster:getObjType() == xi.objType.PC then\n            spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n        else\n            -- e.g. monsters healing themselves.\n            if xi.settings.main.USE_OLD_CURE_FORMULA then\n                basecure = getBaseCureOld(power, divisor, constant)\n            else\n                basecure = getBaseCure(power, divisor, constant, basepower)\n            end\n\n            final = getCureFinal(caster, spell, basecure, minCure, false)\n            local diff = (target:getMaxHP() - target:getHP())\n            if final > diff then\n                final = diff\n            end\n\n            target:addHP(final)\n        end\n    end\n\n    local mpBonusPercent = (final * caster:getMod(xi.mod.CURE2MP_PERCENT)) / 100\n    if mpBonusPercent > 0 then\n        caster:addMP(mpBonusPercent)\n    end\n\n    return final\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/cursna.lua"]={["Path"]="scripts/actions/spells/white/cursna.lua",["SHA256"]="cf16893e16f812cc753542d7fe9c3c08b1abc17eae9ab77ed93c071ba70c476d",["Text"]="-----------------------------------\n-- Spell: Cursna\n-- Removes curse and bane from target.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local curse  = target:getStatusEffect(xi.effect.CURSE_I)\n    local curse2 = target:getStatusEffect(xi.effect.CURSE_II)\n    local bane   = target:getStatusEffect(xi.effect.BANE)\n    local bonus  = caster:getMod(xi.mod.ENHANCES_CURSNA) + target:getMod(xi.mod.ENHANCES_CURSNA_RCVD)\n    local skill  = caster:getSkillLevel(xi.skill.HEALING_MAGIC)\n    local final  = nil\n\n    -- https://www.bg-wiki.com/ffxi/Cursna, https://wiki.ffo.jp/html/1962.html\n    local power = (10 + (skill / 30)) * (1 + (bonus / 100))\n\n    spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n    if\n        target:hasStatusEffect(xi.effect.DOOM) and\n        power > math.randomInt(1, 100)\n    then\n        -- remove doom\n        final = xi.effect.DOOM\n        target:delStatusEffect(xi.effect.DOOM)\n        spell:setMsg(xi.msg.basic.NARROWLY_ESCAPE)\n    elseif curse ~= nil and curse2 ~= nil and bane ~= nil then\n        target:delStatusEffect(xi.effect.CURSE_I)\n        target:delStatusEffect(xi.effect.CURSE_II)\n        target:delStatusEffect(xi.effect.BANE)\n        final = xi.effect.CURSE_II\n        spell:setMsg(xi.msg.basic.MAGIC_REMOVE_EFFECT)\n    elseif curse ~= nil and bane ~= nil then\n        target:delStatusEffect(xi.effect.CURSE_I)\n        target:delStatusEffect(xi.effect.BANE)\n        final = xi.effect.CURSE_I\n        spell:setMsg(xi.msg.basic.MAGIC_REMOVE_EFFECT)\n    elseif curse2 ~= nil and bane ~= nil then\n        target:delStatusEffect(xi.effect.CURSE_II)\n        target:delStatusEffect(xi.effect.BANE)\n        final = xi.effect.CURSE_II\n        spell:setMsg(xi.msg.basic.MAGIC_REMOVE_EFFECT)\n    elseif curse ~= nil then\n        target:delStatusEffect(xi.effect.CURSE_I)\n        final = xi.effect.CURSE_I\n        spell:setMsg(xi.msg.basic.MAGIC_REMOVE_EFFECT)\n    elseif curse2 ~= nil then\n        target:delStatusEffect(xi.effect.CURSE_II)\n        final = xi.effect.CURSE_II\n        spell:setMsg(xi.msg.basic.MAGIC_REMOVE_EFFECT)\n    elseif bane ~= nil then\n        target:delStatusEffect(xi.effect.BANE)\n        final = xi.effect.BANE\n        spell:setMsg(xi.msg.basic.MAGIC_REMOVE_EFFECT)\n    end\n\n    return final\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/deodorize.lua"]={["Path"]="scripts/actions/spells/white/deodorize.lua",["SHA256"]="e7c221f26f99202944a1c81fe654357026247631c442645d4a285e2e6d369840",["Text"]="-----------------------------------\n-- Spell: Deodorize\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useEnhancingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/dia.lua"]={["Path"]="scripts/actions/spells/white/dia.lua",["SHA256"]="1d0db392c40f5f7d45939c89c932bb409d543725aaa2a498f22c94d5422855c6",["Text"]="-----------------------------------\n-- Spell: Dia\n-- Lowers an enemy's defense and gradually deals light elemental damage.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell)\n    local tier   = 1\n\n    -- Check for Bio\n    local bio = target:getStatusEffect(xi.effect.BIO)\n    if\n        not bio or\n        (bio and bio:getTier() < tier)\n    then\n        target:delStatusEffect(xi.effect.BIO)\n        local power = 1 + caster:getMod(xi.mod.DIA_DOT)\n\n        target:addStatusEffect(xi.effect.DIA, { power = power, duration = 60, origin = caster, tick = 3, subPower = 10, tier = tier })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/dia_ii.lua"]={["Path"]="scripts/actions/spells/white/dia_ii.lua",["SHA256"]="dc571070a4c1453d81ba54caa373ecb6486ec8c6f5e9b99174d090d6c7da648b",["Text"]="-----------------------------------\n-- Spell: Dia II\n-- Lowers an enemy's defense and gradually deals light elemental damage.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell)\n    local tier   = 3\n\n    -- Check for Bio\n    local bio = target:getStatusEffect(xi.effect.BIO)\n    if\n        not bio or\n        (bio and bio:getTier() < tier)\n    then\n        target:delStatusEffect(xi.effect.BIO)\n        local power = 2 + caster:getMod(xi.mod.DIA_DOT)\n\n        target:addStatusEffect(xi.effect.DIA, { power = power, duration = 120, origin = caster, tick = 3, subPower = 15, tier = tier })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/dia_iii.lua"]={["Path"]="scripts/actions/spells/white/dia_iii.lua",["SHA256"]="c411cad7c9ef584e1389a95c65fdf924a5a609d22377783979da40f039e5d889",["Text"]="-----------------------------------\n-- Spell: Dia III\n-- Lowers an enemy's defense and gradually deals light elemental damage.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell)\n    local tier   = 5\n\n    -- Check for Bio\n    local bio = target:getStatusEffect(xi.effect.BIO)\n    if\n        not bio or\n        (bio and bio:getTier() < tier)\n    then\n        target:delStatusEffect(xi.effect.BIO)\n        local power = 3 + caster:getMod(xi.mod.DIA_DOT)\n\n        target:addStatusEffect(xi.effect.DIA, { power = power, duration = 180, origin = caster, tick = 3, subPower = 20, tier = tier })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/dia_iv.lua"]={["Path"]="scripts/actions/spells/white/dia_iv.lua",["SHA256"]="0eea3918180deb90e041388cacd7d0abf0ff5af550a2bf928319e5c4f9f4c9b9",["Text"]="-----------------------------------\n-- Spell: Dia IV\n-- Lowers an enemy's defense and gradually deals light elemental damage.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell)\n    local tier   = 7\n\n    -- Check for Bio\n    local bio = target:getStatusEffect(xi.effect.BIO)\n    if\n        not bio or\n        (bio and bio:getTier() < tier)\n    then\n        target:delStatusEffect(xi.effect.BIO)\n        local power = 4 + caster:getMod(xi.mod.DIA_DOT)\n\n        target:addStatusEffect(xi.effect.DIA, { power = power, duration = 180, origin = caster, tick = 3, subPower = 25, tier = tier })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/dia_v.lua"]={["Path"]="scripts/actions/spells/white/dia_v.lua",["SHA256"]="2018413391160e29efce57f550ed87865d954fc3968b8d80bd7665c42a1fa46b",["Text"]="-----------------------------------\n-- Spell: Dia V\n-- Lowers an enemy's defense and gradually deals light elemental damage.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell)\n    local tier   = 9\n\n    -- Check for Bio\n    local bio = target:getStatusEffect(xi.effect.BIO)\n    if\n        not bio or\n        (bio and bio:getTier() < tier)\n    then\n        target:delStatusEffect(xi.effect.BIO)\n        local power = 5 + caster:getMod(xi.mod.DIA_DOT)\n\n        target:addStatusEffect(xi.effect.DIA, { power = power, duration = 180, origin = caster, tick = 3, subPower = 30, tier = tier })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/diaga.lua"]={["Path"]="scripts/actions/spells/white/diaga.lua",["SHA256"]="d32e6385c50d6874a82b88dfc30906f2cc7279b9c7e8055c1237ceb38bde0907",["Text"]="-----------------------------------\n-- Spell: Diaga\n-- Lowers an enemy's defense and gradually deals light elemental damage.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell)\n    local tier   = 1\n\n    -- Check for Bio\n    local bio = target:getStatusEffect(xi.effect.BIO)\n    if\n        not bio or\n        (bio and bio:getTier() < tier)\n    then\n        target:delStatusEffect(xi.effect.BIO)\n        local power = 1 + caster:getMod(xi.mod.DIA_DOT)\n\n        target:addStatusEffect(xi.effect.DIA, { power = power, duration = 60, origin = caster, tick = 3, subPower = 10, tier = tier })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/diaga_ii.lua"]={["Path"]="scripts/actions/spells/white/diaga_ii.lua",["SHA256"]="e8d2358ff67282ee41435b7426453e4423935aa8ca255a5d5812f441bb2b1e75",["Text"]="-----------------------------------\n-- Spell: Diaga II\n-- Lowers an enemy's defense and gradually deals light elemental damage.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell)\n    local tier   = 3\n\n    -- Check for Bio\n    local bio = target:getStatusEffect(xi.effect.BIO)\n    if\n        not bio or\n        (bio and bio:getTier() < tier)\n    then\n        target:delStatusEffect(xi.effect.BIO)\n        local power = 2 + caster:getMod(xi.mod.DIA_DOT)\n\n        target:addStatusEffect(xi.effect.DIA, { power = power, duration = 120, origin = caster, tick = 3, subPower = 15, tier = tier })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/diaga_iii.lua"]={["Path"]="scripts/actions/spells/white/diaga_iii.lua",["SHA256"]="5d3fa87dc2adb0982ddce67f2f6a3cbb0bb399a2fd3f36beb6e8143a2c5549d9",["Text"]="-----------------------------------\n-- Spell: Diaga III\n-- Lowers an enemy's defense and gradually deals light elemental damage.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDam